theorem_types.cached_definition_from_exact_revision:
Allow.DocumentAdvisoryCache.cached_definition_from_exact_revision {store : Allow.DocumentAdvisoryCache.Store}
  {cache : Allow.DocumentAdvisoryCache.Cache} {key : Allow.DocumentAdvisoryCache.Key}
  {entry : Allow.DocumentAdvisoryCache.Entry} {id : Allow.DocumentAdvisoryCache.Id}
  {definition : Allow.DocumentAdvisoryCache.Definition} (valid : Allow.DocumentAdvisoryCache.Valid store cache)
  (hit : Allow.DocumentAdvisoryCache.cacheLookup cache key = some entry)
  (found : Allow.DocumentAdvisoryCache.definitionLookup entry.snapshot id = some definition) :
  store key = some entry.snapshot ∧ definition ∈ entry.snapshot.definitions ∧ definition.id = id

theorem_types.preview_preserves_authority:
Allow.DocumentAdvisoryCache.preview_preserves_authority {store : Allow.DocumentAdvisoryCache.Store}
  {worker : Allow.DocumentAdvisoryCache.Worker} {auth ready permit : Prop} {policy : Allow.DocumentAdvisoryCache.Policy}
  {candidate : Allow.DocumentAdvisoryCache.Candidate} {s : Allow.DocumentAdvisoryCache.State}
  {key : Allow.DocumentAdvisoryCache.Key} {result : Allow.DocumentAdvisoryCache.AdvisoryResult}
  {out : Allow.DocumentAdvisoryCache.State}
  (step : Allow.DocumentAdvisoryCache.Preview store worker auth ready permit policy candidate s key result out) :
  out.head = s.head ∧ out.history = s.history ∧ out.receipts = s.receipts

